/* Shared code following sound; generated by tools/overlay_src.py, stubs replaced by C as functions are matched. Starts at 0x002A2C90 (was sound_002A2C90.c). */
#include "common.h"
#include "include_asm.h"

extern char hero_globals_base[];

/* Stores the requested values and sets change bits for each one that differs from before. */
void set_requested_state_and_mark_changes(int a, int b, int c, int d, int e)
{
    char *p = hero_globals_base + 0x1D;
    *(int *)(p + 0x60) = a;
    if ((unsigned char)p[0x68] != b) {
        p[0x68] = b;
        p[0x6B] |= 1;
    }
    if (*(int *)(p + 0x64) != c) {
        *(int *)(p + 0x64) = c;
        p[0x6B] |= 4;
    }
    if ((unsigned char)p[0x69] != d || (unsigned char)p[0x6A] != e) {
        p[0x6A] = e;
        p[0x69] = d;
        p[0x6B] |= 2;
    }
}
